import { HttpClient } from './HttpClient';
import { FuulEvent } from './types/api';

export const SENT_EVENT_ID_KEY = 'fuul.sent';
export const SENT_EVENT_VALIDITY_PERIOD_SECONDS = 60;
export const SENT_EVENT_CONNECT_WALLET_KEY = 'connect_wallet';
export const SAVED_EVENTS_MAX_SIZE = 10;

export type EventServiceSettings = {
  httpClient: HttpClient;
  debug?: boolean;
};

export class EventService {
  private readonly debug: boolean;
  private readonly httpClient: HttpClient;

  constructor(settings: EventServiceSettings) {
    this.httpClient = settings.httpClient;
    this.debug = !!settings.debug;
  }

  public async sendEvent(event: FuulEvent, projectIds?: string[]): Promise<void> {
    if (this.isDuplicate(event)) {
      this.debug && console.debug(`Fuul SDK: Event is considered duplicate and will not be sent`);
      return;
    }

    if (!projectIds || !Array.isArray(projectIds) || projectIds.length === 0) {
      await this.httpClient.post({ path: 'events', postData: event });
    } else {
      for (const projectId of projectIds) {
        const projEvent = structuredClone({ ...event, project_id: projectId });
        projEvent.metadata.project_id = projectId;
        await this.httpClient.post({ path: 'events', postData: projEvent, queryParams: { project_id: projectId } });
      }
    }

    this.debug && console.debug(`Fuul SDK: Sent '${event.name}' event`);

    this.saveSentEvent(event);
  }

  public isDuplicate(thisEvent: FuulEvent): boolean {
    const SENT_EVENT_KEY = `${SENT_EVENT_ID_KEY}_${thisEvent.name}`;

    const lastSentEvent = localStorage.getItem(SENT_EVENT_KEY);
    if (!lastSentEvent) {
      return false;
    }

    const savedEvent = JSON.parse(lastSentEvent) as FuulEvent & { timestamp: number };

    const nowTimestamp = this.getCurrentTimestamp();
    const timespanSeconds = nowTimestamp - savedEvent.timestamp;
    const savedEventExpired = timespanSeconds > SENT_EVENT_VALIDITY_PERIOD_SECONDS;

    if (savedEventExpired) {
      return false;
    }

    let matchesMetadata = false;
    if (thisEvent.metadata) {
      matchesMetadata =
        savedEvent.metadata.tracking_id === thisEvent.metadata.tracking_id &&
        savedEvent.metadata.project_id === thisEvent.metadata.project_id &&
        savedEvent.metadata.referrer === thisEvent.metadata.referrer &&
        savedEvent.metadata.source === thisEvent.metadata.source &&
        savedEvent.metadata.category === thisEvent.metadata.category &&
        savedEvent.metadata.title === thisEvent.metadata.title &&
        savedEvent.metadata.tag === thisEvent.metadata.tag &&
        savedEvent.user_address === thisEvent.user_address &&
        savedEvent.user?.identifier === thisEvent.user?.identifier &&
        savedEvent.user?.identifier_type === thisEvent.user?.identifier_type &&
        savedEvent.signature === thisEvent.signature &&
        savedEvent.signature_message === thisEvent.signature_message;
    }

    let matchesArgs = false;
    if (thisEvent.args && savedEvent.args) {
      matchesArgs = savedEvent.args.page === thisEvent.args.page;
    }

    return matchesArgs && matchesMetadata;
  }

  private getCurrentTimestamp() {
    return Date.now() / 1000;
  }

  private saveSentEvent(event: FuulEvent): void {
    const SENT_EVENT_KEY = `${SENT_EVENT_ID_KEY}_${event.name}`;
    const SENT_EVENT_LIST_KEY = `${SENT_EVENT_KEY}_all`;

    const timestamp = this.getCurrentTimestamp();
    const eventParams = { ...event, timestamp };

    localStorage.setItem(SENT_EVENT_KEY, JSON.stringify(eventParams));

    if (event.name === SENT_EVENT_CONNECT_WALLET_KEY) {
      const savedEvents = JSON.parse(localStorage.getItem(SENT_EVENT_LIST_KEY) || '[]');
      const simplifiedEvent: {
        name: string;
        user: {
          identifier: string | undefined;
          identifier_type: string | undefined;
        };
        tracking_id: string | undefined;
        page: unknown;
        user_address?: string;
      } = {
        name: event.name,
        user: {
          identifier: event.user?.identifier,
          identifier_type: event.user?.identifier_type,
        },
        tracking_id: event.metadata?.tracking_id,
        page: event.args?.page,
      };
      if ('user_address' in event) {
        simplifiedEvent.user_address = (event as any).user_address;
      }

      const savedEventsNew = [...savedEvents, simplifiedEvent];
      if (savedEventsNew.length > SAVED_EVENTS_MAX_SIZE) {
        savedEventsNew.splice(0, savedEventsNew.length - SAVED_EVENTS_MAX_SIZE);
      }
      localStorage.setItem(SENT_EVENT_LIST_KEY, JSON.stringify(savedEventsNew));
    }
  }
}

// axios is pinned to >=1.17.0 to clear the security advisory cluster (FUU-1795).
import axios, { AxiosInstance, AxiosResponse } from 'axios';

import release from './release.json';

interface HttpClientOptions {
  baseURL: string;
  timeout: number;
  apiKey?: string;
  queryParams?: Record<string, string>;
}

export interface HttpError {
  message: string;
  status?: number;
}

export interface Request {
  path: string;
  postData?: Record<string, unknown>;
  queryParams?: Record<string, unknown>;
}

export class HttpClient {
  private readonly client: AxiosInstance;
  private defaultQueryParams: Record<string, unknown>;

  constructor(options: HttpClientOptions) {
    this.client = axios.create({
      ...options,
      headers: {
        Authorization: `Bearer ${options.apiKey}`,
        'X-Fuul-Sdk-Version': release.version,
      },
    });

    this.defaultQueryParams = options.queryParams || {};
  }

  private makeQueryParams(queryParams?: Record<string, unknown>): Record<string, unknown> {
    return Object.assign({}, this.defaultQueryParams || {}, queryParams || {});
  }

  async get<T>(req: Request): Promise<AxiosResponse<T>> {
    return this.client.request<T>({
      url: req.path,
      params: this.makeQueryParams(req.queryParams),
      method: 'GET',
    });
  }

  async post<T>(req: Request): Promise<AxiosResponse<T>> {
    return this.client.request<T>({
      url: req.path,
      params: this.makeQueryParams(req.queryParams),
      data: req.postData,
      method: 'POST',
    });
  }

  async put<T>(req: Request): Promise<AxiosResponse<T>> {
    return this.client.request<T>({
      url: req.path,
      params: this.makeQueryParams(req.queryParams),
      data: req.postData,
      method: 'PUT',
    });
  }

  async patch<T>(req: Request): Promise<AxiosResponse<T>> {
    return this.client.request<T>({
      url: req.path,
      params: this.makeQueryParams(req.queryParams),
      data: req.postData,
      method: 'PATCH',
    });
  }

  async delete<T>(req: Request): Promise<AxiosResponse<T>> {
    return this.client.request<T>({
      url: req.path,
      params: this.makeQueryParams(req.queryParams),
      data: req.postData,
      method: 'DELETE',
    });
  }
}

