};

const basePath = '/claim-checks';

/**
 * Service for managing claim checks
 */
export class ClaimCheckService {
  private readonly httpClient: HttpClient;
  private readonly _debug: boolean | undefined;

  constructor(settings: ClaimCheckServiceSettings) {
    this.httpClient = settings.httpClient;
    this._debug = settings.debug;
  }

  /**
   * Retrieves claim checks for a user with optional status filtering
   *
   * @param {GetClaimChecksParams} params - User identifier and optional status filter
   * @returns {Promise<GetClaimChecksResponse>} List of claim checks
   */
  public async getClaimChecks(params: GetClaimChecksParams): Promise<GetClaimChecksResponse> {
    const queryParams: Record<string, string> = {
      user_identifier: params.user_identifier,
      user_identifier_type: params.user_identifier_type,
    };

    if (params.status) {
      queryParams.status = params.status;
    }

    const response = await this.httpClient.get<GetClaimChecksResponse>({
      path: basePath,
      queryParams,
    });
    return response.data;
  }

  /**
   * Closes open claim checks, aggregating and signing them for on-chain claiming
   *
   * @param {CloseClaimChecksParams} params - User identifier and claim check IDs to close
   * @returns {Promise<CloseClaimChecksResponse>} Array of signed claim responses ready for on-chain execution
   */
  public async closeClaimChecks(params: CloseClaimChecksParams): Promise<CloseClaimChecksResponse> {
    const response = await this.httpClient.post<CloseClaimChecksResponse>({
      path: `${basePath}/close`,
      postData: {
        userIdentifier: params.user_identifier,
        userIdentifierType: params.user_identifier_type,
        claim_check_ids: params.claim_check_ids,
      },
    });
    return response.data;
  }

  /**
   * Retrieves all claimable claim checks for a user
   * Returns only unclaimed checks with valid (non-expired) deadlines
   *
   * @param {GetClaimableChecksParams} params - User identifier parameters
   * @returns {Promise<GetClaimableChecksResponse>} Array of claimable claim checks
   */
  public async getClaimableChecks(params: GetClaimableChecksParams): Promise<GetClaimableChecksResponse> {
    const response = await this.httpClient.post<GetClaimableChecksResponse>({
      path: `${basePath}/claim`,
      postData: {
        userIdentifier: params.user_identifier,
        userIdentifierType: params.user_identifier_type,
      },
    });
    return response.data;
  }

  /**
   * Gets aggregated totals of claim checks for a user, one row per currency per
   * state. The `unclaimed` array is the umbrella: it contains rows labeled
   * `status: 'open'` (still accumulating, not claimable yet) and
   * `status: 'closed'` (ready to claim on-chain). Expired checks are excluded
   * from open/closed rows. Claimed checks are past claims (`status: 'claimed'`).
   *
   * The optional `reason` filter narrows which rows are summed by earning type
   * without changing the response shape. When omitted, all earning types are
   * merged into one figure per currency and state.
   *
   * @param {GetClaimCheckTotalsParams} params - User identifier and optional status and reason filters
   * @returns {Promise<GetClaimCheckTotalsResponse>} Totals grouped by status and currency
   */
  public async getClaimCheckTotals(params: GetClaimCheckTotalsParams): Promise<GetClaimCheckTotalsResponse> {
    const queryParams: Record<string, string> = {
      user_identifier: params.user_identifier,
      user_identifier_type: params.user_identifier_type,
    };

    if (params.status) {
      queryParams.status = params.status;
    }

    if (params.reason) {
      queryParams.reason = params.reason;
    }

    const response = await this.httpClient.get<GetClaimCheckTotalsResponse>({
      path: `${basePath}/totals`,
      queryParams,
    });
    return response.data;
  }

  /**
   * Returns a paginated list of a user's completed on-chain claim rows for the
   * project. Each row corresponds to one (transaction hash, currency) pair —
   * a single transaction that settled multiple currencies produces multiple
   * consecutive rows sharing the same `hash`. Only claim checks with
   * status = 'claimed' are returned, ordered by claimed_at DESC.
   *
   * `total_count` counts (hash, currency) rows, not distinct transactions.
   * `amount` is a raw integer string — divide by 10 ** currency_decimals
   * before displaying to users.
   *
   * @param {GetClaimHistoryParams} params - User identifier and pagination
   * @returns {Promise<GetClaimHistoryResponse>} Paginated (hash, currency) claim history
   */
  public async getClaimHistory(params: GetClaimHistoryParams): Promise<GetClaimHistoryResponse> {
    const queryParams: Record<string, string | number> = {
      user_identifier: params.user_identifier,
      user_identifier_type: params.user_identifier_type,
    };

    if (params.page !== undefined) {
      queryParams.page = params.page;
    }
    if (params.page_size !== undefined) {
      queryParams.page_size = params.page_size;
    }

    const response = await this.httpClient.get<GetClaimHistoryResponse>({
      path: `${basePath}/claim-history`,
      queryParams,
    });
    return response.data;
  }
}

import { UserIdentifierType } from '../../types/user';

export interface GetClaimableChecksParams {
  user_identifier: string;
  user_identifier_type: UserIdentifierType;
}

export enum ClaimCheckStatus {
  Open = 'open',
  Unclaimed = 'unclaimed',
  Claimed = 'claimed',
}

export interface ClaimCheckItem {
  id: string;
  currency_address: string;
  currency_chain_id: string;
  currency_name: string;
  currency_decimals: number;
  reason: string;
  amount: string;
  status: string;
  deadline_seconds: number;
  created_at: string;
}

export interface GetClaimChecksParams {
  user_identifier: string;
  user_identifier_type: UserIdentifierType;
  status?: ClaimCheckStatus;
}

export interface GetClaimChecksResponse {
  claim_checks: ClaimCheckItem[];
}

export interface CloseClaimChecksParams {
  user_identifier: string;
  user_identifier_type: UserIdentifierType;
  claim_check_ids: string[];
}

export type CloseClaimChecksResponse = ClaimResponse[];

export enum ClaimCheckReason {
  AffiliatePayout = 0,
  EndUserPayout = 1,
}

export interface ClaimResponse {
  /**
   * Unique identifier of the claim check (UUID)
   */
  id: string;

  project_address: string;

  /**
   * User's identifier (normalized/lowercased)
   */
  to: string;

  currency: string;

  /**
   * Currency type (always 1 for ERC20-type tokens)
   */
  currency_type: number;

  /**
   * Token amount as string (with decimals)
   */
  amount: string;

  /**
   * Reason for the payout (0 = AffiliatePayout, 1 = EndUserPayout)
   */
  reason: ClaimCheckReason;

  /**
   * Token ID (always "0" for fungible tokens)
   */
  token_id: string;

  /**
   * Claim deadline as Unix timestamp in seconds
   */
  deadline: number;

  proof: string;
  signatures: string[];
}

export type GetClaimableChecksResponse = ClaimResponse[];

/**
 * Status filter for claim check totals. Unlike the stored `ClaimCheckStatus`,
 * `Unclaimed` here means the umbrella (open + closed rows); use `Closed` to
 * filter to rows that are ready to claim on-chain right now.
 */
export enum ClaimCheckTotalsStatusFilter {
  Claimed = 'claimed',
  Unclaimed = 'unclaimed',
  Open = 'open',
  Closed = 'closed',
}

/**
 * Earning type filter for claim check totals. Distinct from `ClaimCheckReason`,
 * which is the numeric on-chain reason carried on `ClaimResponse`.
 */
export enum ClaimCheckTotalsReasonFilter {
  AffiliatePayout = 'affiliate_payout',
  EndUserPayout = 'end_user_payout',
  AgencyPayout = 'agency_payout',
}

export interface GetClaimCheckTotalsParams {
  user_identifier: string;
  user_identifier_type: UserIdentifierType;

  /**
   * Filter totals to a single state. `open`, `closed`, and `claimed` return only
   * rows of that state (the other array is empty). `unclaimed` returns both `open`
   * and `closed` rows with `claimed` empty. When omitted, all states are returned.
   */
  status?: ClaimCheckTotalsStatusFilter;

  /**
   * Filter totals to a single earning type: `affiliate_payout` is commission earned
   * for referring others, `end_user_payout` is the rebate a user earned on their own
   * activity, `agency_payout` is an agency's share. When omitted, all types are summed
   * into one figure per currency and state.
   *
   * This narrows which rows are summed — it does not change the response shape, and
   * rows carry no `reason` field. To show commission and rebate separately, call twice.
   */
  reason?: ClaimCheckTotalsReasonFilter;
}

/**
 * State of a totals row: `closed` rows are ready to claim on-chain right now,
 * `open` rows are still accumulating and must be closed first, `claimed` rows
 * were already claimed. Note: `closed` corresponds to the stored status
 * `unclaimed` used by other endpoints.
 */
export type ClaimCheckTotalItemStatus = 'claimed' | 'open' | 'closed';

export interface ClaimCheckTotalItem {
  currency_address: string;
  currency_chain_id: string;
  currency_name: string;

  /**
   * Number of decimal places for the token
   */
  currency_decimals: number;

  /**
   * Total amount as string (summed across all claim checks)
   */
  amount: string;

  status: ClaimCheckTotalItemStatus;
}

export interface GetClaimCheckTotalsResponse {
  claimed: ClaimCheckTotalItem[];
  unclaimed: ClaimCheckTotalItem[];
}

export interface UserClaimHistoryItem {
  /**
   * On-chain transaction hash. The same hash may appear in multiple consecutive
   * rows when a single transaction settled more than one currency.
   */
  hash: string;

  /**
   * ISO 8601 UTC date-time string. MAX(claimed_at) over all claim checks in
   * this (hash, currency) group.
   */
  claimed_at: string;

  currency_address: string;
  currency_chain_id: string;
  currency_name: string;
  currency_decimals: number;

  /**
   * Raw integer amount summed over all claim checks in this (hash, currency)
   * group. Divide by 10 ** currency_decimals before display.
   */
  amount: string;
}

export interface GetClaimHistoryParams {
  user_identifier: string;
  user_identifier_type: UserIdentifierType;

  /**
   * 1-indexed page number. Server default: 1.
   */
  page?: number;

  /**
   * Items per page (1-100). Server default: 25.
   */
  page_size?: number;
}

export interface GetClaimHistoryResponse {
  results: UserClaimHistoryItem[];

  /**
   * Count of distinct (hash, currency) rows for this user — not transaction
   * count. A transaction that settled three currencies counts as three.
   */
  total_count: number;

  /**
   * `page + 1` when `page * page_size < total_count`; otherwise `null`.
   */
  next_page: number | null;
}

