      source: getTrafficSource(),
      affiliate_id: getAffiliateId() ?? undefined,
      referrer: getAffiliateId() ?? undefined,
      category: getTrafficCategory() ?? undefined,
      title: getTrafficTitle() ?? undefined,
      tag: getTrafficTag() ?? undefined,
    },
