/**
 * Gets totals of claim checks for a user, one row per currency per state.
 *
 * The `unclaimed` array is the umbrella for two states, labeled per row via
 * `status`: `'open'` (still accumulating, must be closed before claiming) and
 * `'closed'` (ready to claim on-chain right now). A "ready to claim" figure
 * must only sum rows with `status: 'closed'` — or pass `status: 'closed'` to
 * filter server-side. Expired checks are excluded from open/closed rows.
 *
 * The optional `status` filter takes a `ClaimCheckTotalsStatusFilter` member, where
 * `ClaimCheckTotalsStatusFilter.Unclaimed` means the umbrella (open + closed). The
 * members map to the wire values `'claimed' | 'unclaimed' | 'open' | 'closed'`;
 * invalid values return a 400.
 *
 * The optional `reason` filter takes a `ClaimCheckTotalsReasonFilter` member and
 * narrows which rows are summed by earning type. It does not change the response
 * shape — rows carry no `reason` field — so showing commission and rebate
 * separately means calling twice. When omitted, all earning types are merged.
 * @param {GetClaimCheckTotalsParams} params Get claim check totals parameters
 * @returns {Promise<GetClaimCheckTotalsResponse>} Claim check totals grouped by status and currency
 * @example
 * ```typescript
 * const totals = await Fuul.getClaimCheckTotals({
 *   user_identifier: '0x12345',
 *   user_identifier_type: UserIdentifierType.EvmAddress
 * });
 * console.log('Claimed totals:', totals.claimed);
 * const readyToClaim = totals.unclaimed.filter(item => item.status === 'closed');
 * const stillAccumulating = totals.unclaimed.filter(item => item.status === 'open');
 * readyToClaim.forEach(item => {
 *   console.log(`${item.currency_name}: ${item.amount} (${item.currency_address})`);
 * });
 *
 * // Commission earned for referring others, and rebates earned on own activity
 * const ids = { user_identifier: '0x12345', user_identifier_type: UserIdentifierType.EvmAddress };
 * const commission = await Fuul.getClaimCheckTotals({ ...ids, reason: ClaimCheckTotalsReasonFilter.AffiliatePayout });
 * const rebate = await Fuul.getClaimCheckTotals({ ...ids, reason: ClaimCheckTotalsReasonFilter.EndUserPayout });
 * ```
 */
export async function getClaimCheckTotals(params: GetClaimCheckTotalsParams): Promise<GetClaimCheckTotalsResponse> {
  assertInitialized();
  return _claimCheckService.getClaimCheckTotals(params);
}

/**
 * Returns a paginated list of a user's completed on-chain claim rows for the project.
 * Each row corresponds to one `(transaction hash, currency)` pair — when a single
 * transaction settled multiple currencies, the same `hash` will appear in multiple
 * consecutive rows. Only claim checks where `status = 'claimed'` are included.
 * Results are ordered by `claimed_at DESC`, with ties broken by `hash` then `currency`.
 *
 * `total_count` reflects the number of `(hash, currency)` rows, not distinct
 * transaction hashes. `amount` is a raw integer string — divide by
 * `10 ** currency_decimals` before displaying to users.
 *
 * @param {GetClaimHistoryParams} params Get claim history parameters
 * @returns {Promise<GetClaimHistoryResponse>} Paginated `(hash, currency)` claim history
 * @example
 * ```typescript
 * const history = await Fuul.getClaimHistory({
 *   user_identifier: '0x12345',
 *   user_identifier_type: UserIdentifierType.EvmAddress,
 *   page: 1,
 *   page_size: 25,
 * });
 * history.results.forEach(row => {
 *   console.log(
 *     `${row.hash} — ${row.currency_name} on chain ${row.currency_chain_id}: ${row.amount} at ${row.claimed_at}`,
 *   );
 * });
 * ```
 */
export async function getClaimHistory(params: GetClaimHistoryParams): Promise<GetClaimHistoryResponse> {
  assertInitialized();
  return _claimCheckService.getClaimHistory(params);
}

function assertBrowserContext(): void {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    throw new Error(`Fuul SDK: Browser context required`);
  }
}

function detectAutomation(): void {
  if (navigator.webdriver) {
    throw new Error(`Fuul SDK: Error`);
  }
}

function assertValidApiKey(): void {
  if (!_apiKey) {
    throw new Error('Fuul SDK: Invalid API key');
  }
}

function createApiClient(baseUrl: string, defaultQueryParams: Record<string, string>): HttpClient {
  return new HttpClient({
    baseURL: baseUrl,
    timeout: 30000,
    apiKey: _apiKey,
    queryParams: defaultQueryParams,
  });
}

